reg=load(P/'regression.json');assert all(x['exit_code']==0 for x in reg)
counts={}
for x in reg:counts[x['name']]=sum(map(int,re.findall(r'test result: ok\. (\d+) passed;', (P/(x['name']+'.txt')).read_text(encoding='utf-8'))))
assert counts['ports-adapters-lib']==101 and counts['work']==222 and counts['host-lib']==84,counts
