save('source-current.json',{'date':now,'head':head,'branch':branch,'source_hashes':hashes,'based_on':'../../M02/s1/green/source-current.json','changed_this_delivery':changed})
env=load(P/'delivery-green-environment.json');helpers={k:{'path':v,'sha256':sha(pathlib.Path(v))} for k,v in env.items()}
checks=[
('Module boundary','PASS','Only Windows adapter body/private helpers and additive owned tests changed; 790 other inventoried app files unchanged.'),
('Dependency direction','PASS','Ports remain primitive; adapter uses existing SPEC hash and Windows FS/handle. No WORK/HOST/UI wiring or dependency changes.'),
('Public contracts and schema','PASS','Both traits, four methods, receipt/error fields and journal protocol A unchanged; original 215 cases retained byte-for-byte.'),
('Ownership','PASS','Lease owns native share_mode(0) handle; transaction tracks only exclusive-created artifacts. Atomic counter creates IDs only, not a lock/state registry.'),
('Mutation boundary','PASS','Only selected target and owned scratch are changed. acquire validates journal read-only. No recursive cleanup or stale-lock deletion.'),
('Transaction/failure paths','PASS','Prepared -> recheck -> publish -> verify -> committed; rollback verifies original and rolled-back record. Unconfirmed state returns RecoveryRequired and retains versions.'),
('Cleanup','PASS','Hash-verified terminal artifacts only; journal removed last. Committed cleanup failure keeps successful receipt. Partial publish scratch has RED-to-GREEN regression.'),
('Native identity','PARTIAL','Windows10 hard-link and case-alias refusal PASS; reparse and 8.3 alias native coverage remains IO-A-F1, not claimed complete.'),
('Concurrency/lifecycle','PASS','Real child-process lease busy/drop/death and five journal crash/reopen checkpoint cases GREEN on current Windows10.'),
('Architecture changes','PASS','No new Port, module, manager, adapter, ownership model, schema, or transaction guarantee. Native FFI is confined to private handle identity wrapper.'),
('Platform acceptance','NOT RUN','Windows11 x64 required acceptance environment unavailable; Windows10 build19045 cannot satisfy that gate.'),
('System/release','NOT RUN','No HOST/UI integration, installer, DCC, full-system test, commit, push or release in this slice.')]
review={'at':now,'reviewer':'same assistant; separate static conformance pass after GREEN, no separately delegated reviewer','architecture_verdict':'PASS_WITHIN_APPROVED_ENVELOPE','acceptance_verdict':'PARTIAL_WINDOWS11_NATIVE_GATE_PENDING','checks':[{'item':a,'status':b,'evidence':c}for a,b,c in checks],'blocking_architecture_findings':[]}
save('architecture-review.json',review)
