for i in range(1,19):
 names=[n for n in green if re.match(r'io_'+f'{i:02}',n)]
 trace.append({'requirement':'IO module contract '+str(i),'bdd':f'IO-BDD-{i:02}','tests':names,'result':'PASS_CURRENT_HOST','formal_windows11':'NOT RUN'})
