save('module-spec.json',spec)
esc=html.escape
sections=[]
def section(title,body):sections.append('<section><h2>'+esc(title)+'</h2>'+body+'</section>')
def table(head,rows):return '<table><thead><tr>'+''.join('<th>'+esc(str(c))+'</th>'for c in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+esc(str(c))+'</td>'for c in row)+'</tr>'for row in rows)+'</tbody></table>'
def pre(x):return '<pre>'+esc(x)+'</pre>'
section('1. 模組摘要與交付範圍','<p>File Commit 提供單一正式文件的安全提交基礎：持有寫入權、檢查預期版本、發布完整內容，失敗時回復或保留可診斷版本。這次交付核准 IO-PREREQ 的產品行為；沒有接入 HOST/UI。</p><p><strong>GREEN 220 / 220；回歸 407 項 PASS；架構符合核准 envelope。整體驗收 PARTIAL：Windows 11 實機 gate 尚未執行。</strong></p>')
section('2. 工程基線與已取代規則','<p>方案 A、IO-G1～G6 及 Skeleton/196 項有效 RED 已驗收。原文件「未授權產品實作」是歷史狀態，已由 Owner 的產品自動實作持續授權及本次 IO 明確任務取代；不是重新批准架構。舊 8-byte magic 規則仍被方案 A 的 9-byte magic 取代。</p>'+table(['項目','證據'],[['branch',branch],['HEAD',head],['protocol SHA256',sha(protocol)],['原 RED','196 缺行為失敗 + 19 support PASS；本輪先重現'],['來源範圍','792 檔盤點；只變更 adapter 與追加測試，790 檔未變']]))
section('3. 六角架構與模組依賴',pre('Driving: tests / future HOST (unchanged)\n       ↓ FileCommitPort / FileWriteLease\nWindows FileCommit Adapter [single-file transaction]\n       ↓ Windows FS / native handle / existing SPEC hash\n\nHOST → PORTS ← ADAPTERS → existing SPEC hash\nWORK Domain / UI: no new dependency')+'<p>上圖投影自已採納架構，沒有增加服務或改變分層。</p>')
section('4. Ports、Adapters、狀態與交易邊界',table(['邊界','規則'],[['Input Port','create_directory_exclusive / acquire_write；lease.read_current / replace_checked'],['Output / driven','現有 Windows filesystem/native handle 與 SPEC SHA256；無新依賴'],['Authoritative state','正式文件仍為正式資料；journal 只表示該次交易，非 M07 快照或專案 SSOT'],['Ownership','lease 擁有 OS handle；單次交易只追蹤 exclusive-create 取得的暫存'],['Mutation','持鎖 replace 修改單一目標；acquire 只讀辨識，不恢復或清理'],['Transaction','Acquire → Validate → PrepareOld/New → PREPARED → Recheck → Publish → Verify → COMMITTED → Receipt；失敗 Restore → Verify → ROLLED_BACK，無法確認則 RecoveryRequired']]))
section('5. 契約與不變量',table(['階段','成功／失敗規則'],[[r['phase'],r['result']+'；'+r['preservation']]for r in spec['contracts']]))
section('6. 禁止依賴與保護範圍','<p>不改公開 Port/API、schema、ownership、交易語意、Undo、M07 清理政策。沒有 Domain→FS、UI→adapter、隱藏全域鎖、遞迴刪除或按鎖檔年齡刪鎖。原生 unsafe 僅在私有 handle identity FFI 包裝內，crate 其他 unsafe 禁制不變。</p>')
